-- 小区基础数据 完整备份（结构 + 全部数据 + AUTOINCREMENT 自增水位）。
--
-- 来源：persist/community_data.sqlite3 于 2026-09-02 导出，共 11641 行业务数据。
-- 恢复方式：对"空库"执行本文件（语句不带 IF NOT EXISTS，等价 sqlite3 .dump）：
--   sqlite3 新库.db < 本文件   或   Python: connection.executescript(文本)
-- 数据核对：恢复后各表行数与内容应与生产库一致（导出时已做回验）。
BEGIN TRANSACTION;
CREATE TABLE communities (
    community_id INTEGER PRIMARY KEY AUTOINCREMENT,
    community_group_id INTEGER NOT NULL,
    city TEXT NOT NULL,
    administrative_district TEXT NOT NULL,
    district TEXT,
    name TEXT NOT NULL,
    normalized_name TEXT NOT NULL,
    phase TEXT,
    phase_key TEXT NOT NULL,
    aliases_json TEXT NOT NULL DEFAULT '[]',
    build_year INTEGER,
    address TEXT NOT NULL,
    longitude REAL,
    latitude REAL,
    coordinate_system TEXT,
    geocode_status TEXT NOT NULL DEFAULT 'PENDING',
    geocode_level INTEGER,
    geocode_reliability INTEGER,
    geocode_message TEXT,
    remark TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL, estate_type TEXT,
    FOREIGN KEY (community_group_id)
        REFERENCES community_groups(community_group_id),
    UNIQUE(city, administrative_district, normalized_name, phase_key)
);
